insert into matcha_articles (url, lang, prefecture_code, title, body, images, published_at, place, text_attribution, text_attribution_url)
values
(E'https://matcha-jp.com/tw/11319', E'zh-Hant', 32, E'【島根】奇岩怪石、神社、美麗絕景滿滿的隱岐島旅', E'島根縣北方海上的隱岐群島，島上的觀光資源相當豐富！這次就由MATCHA小編帶大家實際走一遭，以最實際與最詳盡的親身體驗介紹隱岐的美食、大自然與歷史人文的全方面魅力。\n\n隱岐島位於島根縣北方約50公里的海上，是一座擁有許多歷史、神話還有更多豐富地形的群島。\n\n要前往隱岐島有多種交通手段。最快速但班次不多的就是從大阪的伊丹機場或出雲機場搭乘飛機至隱岐機場；另外就是從七類港或境港搭乘隱岐汽船公司的渡輪或高速船前往。\n\n島前三島之間的交通就可搭乘這個內航船。航行距離與時間不長，但有大型行李的人推薦放置行李區，不推薦拿至座席。可以至觀光案內所購買1,000日圓的2day pass讓旅行更方便划算。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/09/01-129414.webp","https://resources.matcha-jp.com/resize/720x2000/2022/09/05-129532.webp","https://resources.matcha-jp.com/resize/720x2000/2022/08/26-129278.webp","https://resources.matcha-jp.com/resize/720x2000/2022/08/26-129279.webp"]'::jsonb, E'2022-08-26'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/3744', E'zh-Hant', 33, E'倉敷中央醫院', E'公益財團法人大原紀念倉敷中央醫療機構倉敷中央醫院（日語：倉敷中央病院／くらしきちゅうおうびょういん）是日本岡山縣倉敷市的公益法人醫院。\n\n發行文件使用的簡稱為倉中或KCH。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/08/15-83970.webp","https://resources.matcha-jp.com/resize/720x2000/2019/08/15-83972.webp","https://resources.matcha-jp.com/resize/720x2000/2019/08/14-83928.webp","https://resources.matcha-jp.com/resize/720x2000/2019/08/14-83929.webp"]'::jsonb, E'2017-07-22'::timestamptz, E'倉敷中央醫院', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E5%80%89%E6%95%B7%E4%B8%AD%E5%A4%AE%E9%86%AB%E9%99%A2'),
(E'https://matcha-jp.com/tw/24300', E'zh-Hant', 33, E'【2025】岡山櫻花隱藏版景點10選！最佳花期、夜間燈光秀與賞櫻景點完整指南', E'本文將介紹岡山的櫻花名所10選，從岡山後樂園及津山城等經典景點已經很出名了，這次還要介紹隱藏版秘境櫻花景點，詳細解說最佳花期與開花資訊。同時也包含賞櫻活動與夜間燈光秀的相關資訊，為您提供一份不論白天或夜晚都能盡情享受的絕美景點完整指南！\n\n岡山的主要賞櫻景點每年大約在3月下旬至4月中旬迎來滿開季節，包括染井吉野櫻、八重櫻、枝垂櫻等各種櫻花。\n\n岡山有許多著名的賞櫻景點，各地都會舉行白天和夜間的櫻花燈光秀及櫻花祭，為前來的遊客提供歡樂的氣氛，是適合賞花的絕佳地點。\n\n在岡山，櫻花每年大約從3月下旬至4月中旬進入滿開，並且各個景點都能欣賞到不同特色的景色。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/02/27-226238.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/27-226239.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/27-226241.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/27-226245.webp"]'::jsonb, E'2025-03-06'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/17332', E'zh-Hant', 33, E'【山口・廣島・岡山】3天2夜自行車之旅！享受絕佳美景、歷史景點、當地美食', E'山口縣以壯觀的石灰岩台地而聞名，廣島縣擁有充滿懷舊氣息的港町，岡山縣的牛仔褲街獨樹一格，本篇將介紹橫跨三縣的3天2夜自行車之旅，旅途中可以品味美景、探訪人文歷史，並品嚐特色美食！\n\n本篇將介紹位於日本本州西部的山口、廣島、岡山三縣的3天2夜自行車之旅，旅途中盡情享受各縣的美景、探訪悠久的人文歷史，並品味當地的特色美食。對於喜愛騎自行車旅遊的人來說，這絕對是一個不可錯過的精彩經歷！\n\n※本文所提供的情報為採訪時的內容。文章內提到的商品、服務內容或是價格等可能會有所更動，請實際以店家提供資訊為準。\n\n據說湯田溫泉是由白狐所發現的溫泉，每天湧出高達2,000噸的豐沛溫泉水量。由於其泉質是鹼性溫泉，被稱為美肌之湯，據說具有保濕效果。湯田溫泉站的外面豎立著一座巨大的白狐石像，這是個絕佳的拍照機會。此外，車站旁與街道上設有足湯設施，供自行車騎士在此放鬆疲憊的肌肉。', E'["https://resources.matcha-jp.com/resize/720x2000/2023/12/06-155286.webp","https://resources.matcha-jp.com/resize/720x2000/2023/12/06-155288.webp","https://resources.matcha-jp.com/resize/720x2000/2023/12/06-155292.webp","https://resources.matcha-jp.com/resize/720x2000/2023/12/06-155294.webp"]'::jsonb, E'2023-12-06'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/4950', E'zh-Hant', 34, E'日本第一的檸檬產地廣島縣：精選6樣廣島檸檬伴手禮', E'一走進廣島縣的伴手禮店，一定會看到許多檸檬商品映入眼簾。廣島縣為日本第一的檸檬生產地，這次我們將介紹廣島伴手禮店常見的檸檬商品，在購買伴手禮時請務必參考本篇文章喔！\n\n氣候溫暖且少雨的瀨戶內海(※1)沿岸，是最適合栽培柑橘類的地區。其中特別是廣島縣，日本產的檸檬一半以上都是在那裡栽培的。\n\n即使是在廣島縣以外的地區也常使用「廣島檸檬」、「瀨戶內檸檬」這個賣點來製作許多的商品販售。\n\n雖然大眾對於檸檬的印象就是酸，但是現在市面上也有許多將酸味調整而變得不再那麼難以下嚥的商品，請務必挑戰看看！', E'["https://resources.matcha-jp.com/resize/720x2000/2017/08/31-34949.webp","https://resources.matcha-jp.com/resize/720x2000/2017/08/31-34950.webp","https://resources.matcha-jp.com/resize/720x2000/2017/08/31-34951.webp","https://resources.matcha-jp.com/resize/720x2000/2017/08/31-34952.webp"]'::jsonb, E'2018-02-13'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/26999', E'zh-Hant', 34, E'深入體驗廣島的四條深度遊路線 | 歷史、美食與文化旅遊指南', E'本文將介紹四條體驗式旅遊線路，讓您從多個角度領略廣島的歷史、美食和文化。從和平教育到夜間美食之旅，再到宮島傳統文化體驗，我們將為您展現廣島的魅力，讓您的旅程更加充實。\n\n近年來，讓參與者在當地導遊的帶領下深入學習、品嚐和感受的「體驗式旅遊」越來越受歡迎。例如，帶領遊客參觀和平紀念公園和原子彈爆炸圓頂屋的徒步之旅，可以讓您了解歷史，體驗廣島的重建歷程及其對和平的承諾。\n\n本次旅程將帶您參觀和平紀念公園和和平紀念博物館等重要景點，這兩個景點均被聯合國教科文組織列為世界遺產，讓您更深入地了解廣島的過去及其和平的信息。\n\n此外，行程還包括一些簡單的文化體驗，例如摺紙鶴，以及靜思冥想的時間。漫步後，您可以在折鶴塔頂層享用午餐，同時飽覽廣島全景。', E'["https://resources.matcha-jp.com/resize/720x2000/2026/03/28-261781.webp","https://resources.matcha-jp.com/resize/720x2000/2026/03/29-261795.webp","https://resources.matcha-jp.com/resize/720x2000/2026/03/29-261796.webp","https://resources.matcha-jp.com/resize/720x2000/2026/03/28-261783.webp"]'::jsonb, E'2026-03-28'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/24761', E'zh-Hant', 34, E'日本Outlet新選擇！THE OUTLETS 享盡美食娛樂＆免稅購物樂趣！', E'說到來日本血拼購物，許多人都會特地造訪知名大型 OUTLET 購物中心。AEON集團近年全新打造的「THE OUTLETS」系列是位於福岡縣北九州、廣島、以及神奈川平塚的AEON集團旗下的outlet購物中心，目標成為在地人與外國旅客都想前往的全方位型商城。從時尚精品、家電賣場、在地美食到親子設施，一站搞定所有需求，讓我們一起深入認識這個全新購物樂園吧！\n\n從親子家庭、情侶到銀髮族，各年齡層的訪客都能享受多元的空間規劃與貼心設施，是一種「不只是為了買東西」的全新購物體驗方式。\n\nTHE OUTLETS 系列目前在日本主要都市近郊設有多個據點，包括中國地區的「THE OUTLETS HIROSHIMA（廣島）」、「THE OUTLETS KITAKYUSHU（北九州）」以及關東的「THE OUTLETS SHONAN HIRATSUKA（湘南平塚）」，設施空間設計各具特色，以下我們將會深入介紹這三間分店的魅力。\n\nTHE OUTLETS KITAKYUSHU 匯聚了約 300 間品牌店舖，包括 mont-bell、Nike、HUGO BOSS、ARMANI、COACH 等知名品牌也都進駐其中，讓購物就像是在「尋寶」一般，樂趣無窮。 在步行範圍內，還有九州知名的大型購物中心「AEON永旺夢樂城八幡東」，若能一併造訪，將能度過更加充實的一天。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/06/15-236604.webp","https://resources.matcha-jp.com/resize/720x2000/2022/09/19-129900.webp","https://resources.matcha-jp.com/resize/720x2000/2025/06/16-236675.webp","https://resources.matcha-jp.com/resize/720x2000/2025/06/16-236676.webp"]'::jsonb, E'2025-04-23'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/7855', E'zh-Hant', 35, E'角島大橋', E'角島大橋是位於日本山口縣下關市豐北町神田地區和角島之間，跨越海士瀨戶的橋梁，為山口縣道276號角島神田線的一部分；橋上最高限速為40公里每小時，當風勢過大時會禁止一般車輛通行。\n\n大橋位於北長門海岸國定公園的範圍內，在興建時考慮到與周邊景觀及生態環境的配合，除了控制橋梁本身的高度，路線也特地不採用傳統穿過中間小島的做法，而是繞過鳩島從一旁經過，獲得相當高的評價，在2003年獲得「土木學會設計獎2003」的優秀獎。\n\n由於角島大橋經過的這片海域的海床上有許多細碎貝殼形成的砂灘，清澈的海水在陽光的照射下會形成翠綠色，在通車後吸引包括四日間的奇蹟、HERO特別篇等許多電視劇和汽車商的電視廣告到此取景拍攝，也逐漸成為熱門的觀光景點，現在在靠豐北町神田地區一側設有海士瀨公園及角島大橋展望台，在角島一側設有瀨崎陽公園，每年約有90萬旅客到此。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/09/05-85279.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/05-85300.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/05-85280.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/05-85281.webp"]'::jsonb, E'2019-10-31'::timestamptz, E'角島大橋', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E8%A7%92%E5%B3%B6%E5%A4%A7%E6%A9%8B'),
(E'https://matcha-jp.com/tw/8100', E'zh-Hant', 35, E'從九州門司港玩到山口下關！「赤間神宮」如龍宮殿的傳說景點', E'山口下關與九州門司港相隔不遠，許多人都會將山口「赤間神宮」排入行程。這裡流傳著許多傳說，供奉源平之戰戰敗跳海自盡的安德天皇及平家一族，也是日本怪談「無耳芳一」的背景舞台。各種故事讓赤間神宮瀰漫一股不可思議氣息，加上週邊美麗的景緻，來山口觀光不來實在可惜！\n\n山口縣下關市的赤間神宮，供奉源平之戰戰敗跳海自盡的安德天皇及平家一族，除此之外更是日本家喻戶曉的怪談「無耳芳一」的背景舞台。各種故事，讓赤間神宮瀰漫一股不可思議氣息，許多觀光客因此前往朝聖。\n\n在山口縣下關市有一座流傳怪談的赤間神宮，供奉安德天皇與平家物語的平家一族。 平安時代末期，源平合戰於現在的下關附近進行壇之浦決戰。而敗北的平家成員，帶著流有平家血統、才八歲的安德天皇一同跳海自盡，平家宣告滅亡。不久後便發生文治大地震，相傳是安德天皇年幼的怨靈所致，戰勝掌握局勢的源氏便建造阿彌陀寺供奉安德天皇。 而後在明治維新的「神佛分離令」實施後，阿彌陀寺改為天皇社，之後升格為神宮。\n\n穿過鳥居後便是水天門，因為安德天皇投水後遺體未曾尋獲，所以建造時認為他的玉體雖在水底，但是尊貴的靈魂必在天上，因此被供奉為「水天皇大神」，這就是水天門名字的由來。此外，日本許多地方可見的水天宮，也都是供奉安德天皇。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/10/10-87907.webp","https://resources.matcha-jp.com/resize/720x2000/2019/10/10-87908.webp","https://resources.matcha-jp.com/resize/720x2000/2019/10/10-87909.webp","https://resources.matcha-jp.com/resize/720x2000/2019/10/10-87910.webp"]'::jsonb, E'2019-10-10'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/1603', E'zh-Hant', 35, E'【山口絕景】日本最難丟香火錢的「元乃隅稻成神社」', E'本篇文章介紹的是位於山口縣的元乃隅稲成神社，它於2015年，被選為美國CNN電視臺“日本最美的31道風景”，景色的絕美也是世界認同的。同時，這裏還有最難被投入香火錢的賽錢箱。歡迎大家前來旅遊參觀。\n\n在日本的神社中有著投香火錢求願的習俗。一般神社內都設有專用的香火錢箱，但這之中也不乏一些神社想盡辦法不讓妳投香火錢。\n\n這次我們介紹的就是間據說只要成功投入香火錢就一定能心想事成的神社，它就是擁有世界絕景的“元乃隅稻成神社”。 小編推薦延伸閱讀 【日本文化小百科】神社的參拜方法\n\n元乃隅稻成神社位於傍山傍海，自然豐富的山口縣長門市。神社的起源要追溯到1955年，當地的一個漁夫夢到了白狐，白狐對他說：“快去建造一間供奉自己的神社”，於是就有了現在的元乃隅稻成神社。', E'["https://resources.matcha-jp.com/old_thumbnails/200x2000/874.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/25-123262.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/25-123263.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/25-123264.webp"]'::jsonb, E'2018-06-29'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/12008', E'zh-Hant', 36, E'【最新】德島縣觀光全攻略！必去景點12選及當地推薦美食、祭典活動簡介', E'充滿傳統文化和豐富自然魅力的四國德島，除了經典景點鳴門漩渦、大步危小步危等，還有其他熱門觀光景點，本篇文章整理出德島12個推薦旅遊景點，以及德島特有的地方美食與阿波舞等活動資訊供參考。\n\n德島縣位於四國島東側，隔著鳴門海峽與兵庫縣的淡路島相望，同樣位於四國地區的還有香川縣、愛媛縣與高知縣，不但是聞名世界的阿波舞的發源地、同時擁有如鳴門漩渦、祖谷葛藤橋等多數自然絕景。\n\n德島縣內多山地，受此影響全縣大約可分成3種氣候，北部溫暖少雨、南部溫暖多雨、西部則低溫多雨；但整體來說日照時間長、晴天日數多，四季皆有不同的景致與活動。春天的平均溫度約落在15～20度之間，新綠吐芽、百花綻放、氣溫逐漸回暖，非常舒服且適合外出，是最推薦的旅遊季節。\n\n前往德島縣的交通方式可分為飛機、鐵路（新幹線+特急列車，需轉乘）、巴士和渡輪。東京羽田與福岡博多皆有直達德島阿波舞機場的航班，飛行時間約為70分鐘；也可選擇直接飛到有位於香川縣、有台灣直航班機的高松機場後，再轉乘JR或巴士進入德島縣。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/02/17-224654.webp","https://resources.matcha-jp.com/resize/720x2000/2023/05/15-138208.webp","https://resources.matcha-jp.com/resize/720x2000/2023/05/15-138213.webp","https://resources.matcha-jp.com/resize/720x2000/2023/05/15-138214.webp"]'::jsonb, E'2023-05-26'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/21268', E'zh-Hant', 36, E'大啖會跳舞的雞肉！德島美食4選： 阿波尾雞、德島風御好燒、鯛魚拉麵、祖谷蕎麥麵', E'德島縣位於四國東部，由鳴門大橋連接住兵庫縣的淡路島，如果自駕的話從大阪進出也相當容易，交通便捷。當地以農業、畜牧業為主，除了盛產鳴門金時地瓜之外，還有阿波尾鶏、鳴門鯛等肉品。今天就跟小編一起品嚐使用德島新鮮地產食材的美食吧！\n\n德島縣面向太平洋及瀨戶内海，海洋觀光資源豐富，其中鳴門海峽的旋渦就是造訪德島時必訪的景點之一。而在鳴門海峡有名的漩渦中成長的鯛魚「鳴門鯛」，是德島縣代表性的美食，由於生長在漩渦當中因此運動量十足，所以肉質相當緊實及肥厚，跟我們平常吃到的鯛魚很不一樣。\n\n「堂之浦」是德島縣內知名的人氣拉麵店，如果你會去鳴門看漩渦，可以選擇去本店，不然在德島站前也有分店。堂之浦提供的拉麵，湯頭清澈卻有著濃郁的海鮮甜味，清麗淡雅的味道，你不用邊吃邊喝水，完全沒有膩感，不喜濃郁湯頭的人一定會愛上。 堂之浦鳴門本店\n\n帶骨鳥絕對不只有香川縣專美，德島縣也利用有名的阿波尾雞來做帶骨雞肉料理，相同美味可口。阿波尾雞使用天然方式飼養，是地雞的一種，由雄性鬥雞和其他品種混合改良而成的特別品種。阿波尾雞要飼養80日才合格，據說因為牠走路時的尾部像阿波舞的舞姿，因此而得名。因為阿波尾雞經過改良，使其肉質更軟腍，帶清香又不油膩，所以很快便在日本國內十分受歡迎。目前德島的阿波尾雞，是日本全國地雞產量的第一名。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/08/26-194211.webp","https://resources.matcha-jp.com/resize/720x2000/2024/08/26-194210.webp","https://resources.matcha-jp.com/resize/720x2000/2024/08/26-194203.webp","https://resources.matcha-jp.com/resize/720x2000/2024/08/26-194204.webp"]'::jsonb, E'2024-08-26'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/6623', E'zh-Hant', 36, E'沒吃過別說來過『德島』 必吃經典美食四選', E'每年夏天四國德島的夏季祭典「阿波舞」祭都吸引大批超過百萬觀光人潮到訪，另外還有壯觀的鳴門渦潮、四國遍路等熱門景點。好景點當然也要配好美食！Matcha小編整理出到德島在地人推薦必吃美食4選，有會跳阿波舞的阿波舞雞、擁有竹香的竹輪⋯，有機會來四國觀光一定不能錯過！\n\n到德島絕不能錯過會在嘴裡跳「阿波舞」的阿波尾雞、鄉土料理蕎麥米雜炊和聞得到竹香的竹輪，最後來一杯沁涼醋橘汁，祭完五臟廟再去欣賞「阿波舞」吧！\n\n德島產醋橘（すたち）在市場上占了9成以上，是德島著名特產，德島縣廳更以醋橘為形象創作出「醋橘君」吉祥物，發行LINE貼圖，可見德島人對醋橘認同度很高。 日本料理中很常見到醋橘，烤魚上淋上醋橘，酸甜的氣味不僅去油解膩，更添食物香味。\n\n醋橘富含維他命C、E和鈣，除了被認為是美顏聖品外，對預防高血壓、成人病也頗有成效。德島居酒屋裡，不論沙瓦、highball角嗨、雞尾調酒裡多會有醋橘口味。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/09/24-63360.webp","https://resources.matcha-jp.com/resize/720x2000/2018/09/24-63359.webp","https://resources.matcha-jp.com/resize/720x2000/2018/09/24-63357.webp","https://resources.matcha-jp.com/resize/720x2000/2018/09/24-63355.webp"]'::jsonb, E'2018-11-13'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/24700', E'zh-Hant', 37, E'【2025】瀨戶內國際藝術祭推薦10大新作藝術！按島嶼及地區介紹注目作品', E'在「瀨戶內國際藝術祭2025」中將展出的注目新作藝術一次介紹給您。這場日本規模最大的現代藝術活動，將於2025年4月至11月舉行，並展示歷來最多的256件作品。計劃前往瀨戶內藝術祭的您，不妨參考本篇文章，掌握亮點作品吧！\n\n在香川縣與岡山縣，將於2025年4月至11月期間舉辦「瀨戶內國際藝術祭2025」。\n\n這是第6屆舉辦，同時也是疫情結束後的首次活動，展出數量創下歷史新高，共展出256件藝術作品。\n\n其中最值得注目的是「空編織」。這件作品是透過藝術家與瀨戶內諸島居民共同編織漁網，連結人群、海洋、島嶼的記憶，重新詮釋地方風景的藝術作品。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/04/17-231323.webp","https://resources.matcha-jp.com/resize/720x2000/2025/04/17-231324.webp","https://resources.matcha-jp.com/resize/720x2000/2025/04/17-231325.webp","https://resources.matcha-jp.com/resize/720x2000/2025/04/17-231334.webp"]'::jsonb, E'2025-04-17'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/3936', E'zh-Hant', 37, E'高松和小豆島必做的23件事！從觀光景點到必點烏龍麵一次推薦給您', E'高松市是四國地方、香川縣最大的都市。從大阪或是京都出發，搭乘新幹線、高速巴士大約2〜4小時左右可以抵達，是處能夠欣賞瀨戶內海沿岸美麗風景的城市。在高松的話推薦來趟烏龍麵名店巡禮，或是在栗林公園內欣賞日本式庭園美景。若是前往小豆島則建議可到寒霞溪、天堂之路等自然美景交織之處，好好感受美的薰陶。\n\n此展示有20世紀代表雕刻家野口勇之150件作品的美術館。以野口勇抱持著「希望給予下個世代藝術家靈感」的概念所建成，若是想要見學參觀的話，須於十天前以明信片提出申請。\n\n開館日：週二、週四、週六 ※預約制 票價：一般、大學生 2,000日圓(不含稅)／高中生 1,000日圓(不含稅)／國中生以下免費 地址： 香川縣高松市牟禮町牟禮3519 官網：http://www.isamunoguchi.or.jp/\n\n高松城是距今500年前左右建成的城堡，即便在日本也是極為罕見，面海而建的城堡。雖說大部分的城堡都已經不復存在，但還有像是月見櫓等城牆的一部分和石垣還殘留著。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/01/26-15048.webp","https://resources.matcha-jp.com/resize/720x2000/2017/01/26-15047.webp","https://resources.matcha-jp.com/resize/720x2000/2023/10/17-149084.jpeg","https://resources.matcha-jp.com/resize/720x2000/2017/01/26-15046.webp"]'::jsonb, E'2018-04-13'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/7584', E'zh-Hant', 37, E'【香川】瀨戶內頂級絕景！日本第一夕陽父母濱旁的紫雲出山推薦景點7選', E'被譽為「日本第一夕陽絕景」的香川縣父母濱旁邊的莊內半島是瀨戶內海頂級絕景景點。這裡被大海、山、島圍繞，有很多秘境海灘可享受無上的休閒時光。本文介紹精選的7處紫雲出山絕景、咖啡店和住宿設施。\n\n在位於香川縣西部、被譽為「日本第一夕陽絕絶景」的父母濱旁邊的莊內半島上，有紫雲出山、瀨戶內海和山、島等交織的眾多絕景景點。\n\n瀨戶內海放晴的日子較多，令人感到如歐洲地中海般的陽光明媚。在此之中，莊內半島要數秘境海灘的寶庫，是一處能夠邊聽著安靜浪濤聲邊放鬆的最佳場所。\n\n本文以紫雲出山為中心，為大家介紹莊內半島相關的故事以及推薦景點、交通方式等資訊！', E'["https://resources.matcha-jp.com/resize/720x2000/2019/07/01-80607.webp","https://resources.matcha-jp.com/resize/720x2000/2019/06/27-80454.webp","https://resources.matcha-jp.com/resize/720x2000/2019/07/01-80626.webp","https://resources.matcha-jp.com/resize/720x2000/2019/06/27-80455.webp"]'::jsonb, E'2019-08-20'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/4087', E'zh-Hant', 38, E'松山城', E'松山城是愛媛縣松山市的日本城堡，別名「金亀城」、「勝山城」。為了與日本其他的松山城區分，也稱作「伊予松山城」。遺址的大部分區域目前作為公園開放。\n\n包括大天守（日本12座現存天守之一）在內的21座現存建築物被指定為國家重要文化財產，城郭的遺構為國之史蹟。目前以木造結構重修了22座建築，包括於1933年火災中焚毀的小天守等5座建築。\n\n松山城被收錄於2009年米其林指南的綠色封皮觀光版中，評價為2星。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/02/27-19970.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/27-19971.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/26-19890.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/26-19898.webp"]'::jsonb, E'2017-02-27'::timestamptz, E'松山城', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E6%9D%BE%E5%B1%B1%E5%9F%8E_(%E4%BC%8A%E4%BA%88%E5%9B%BD)'),
(E'https://matcha-jp.com/tw/10574', E'zh-Hant', 38, E'成為電影場景的那個車站！ 四國鐵道攝影推薦景點3選', E'四國被瀨戶內海和太平洋所環繞，且中央有山脈橫斷， 在這個保留了許多日本原始景觀的島上，有許多可以在大海、群山及河流的背景下拍攝鐵路美景的景點。 這次，我們將為您介紹從JR下灘站開始，包含德島縣和愛媛縣的鐵道攝影愛好者必去的3個景點！\n\n夾在瀨戶內海和太平洋之間，擁有山脈橫貫中央的四國擁有海、山、河等多種壯麗景色。 在四國有很多地方可以拍攝獨特的鐵路照片！\n\n在這篇文章中，居住在四國的小編將介紹位在愛媛縣和德島縣的3個可以拍攝鐵路照片的景點。\n\n本次介紹的均為JR四國的路線，在這些路線上，有運行著麵包超人列車、觀光列車「伊予灘物語」和「四國真中千年物語」等色彩繽紛的列車，想必讓您大飽眼福！', E'["https://resources.matcha-jp.com/resize/720x2000/2022/03/09-123702.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/09-123703.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/09-123704.webp","https://resources.matcha-jp.com/resize/720x2000/2022/03/09-123705.webp"]'::jsonb, E'2021-07-16'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/4371', E'zh-Hant', 38, E'殘留日本古老街道風情的「小京都」！盡情享受愛媛縣大洲市的5個景點', E'京都，保存有日本古街道！而你知道，在全日本中也有許多有著如同京都特色的小京都嗎。本文章透過Google街景服務將要介紹玩樂大洲市的魅力。\n\n有一稱是”伊予(※a1)的小京都”愛媛縣南部城市「大洲市」。本文章透過Google街景服務，將要介紹玩樂大洲市的5大重點。\n\n大洲市內中心有著建於1331年的「大洲城」，曾作為城下町而發展。由於建築老化之故，當初建成的天守閣(※2)已經毀損，現今看到的是於2004年所復建而成。可從天守閣眺望大洲市街景。\n\n此景為大洲城內部樣貌。現今復原的天守閣是個4樓的木造建築，全部都使用日本產木材。樑所使用的木材是有著350年歷史的木曽檜木，柱所用的是在地愛媛的木材，而地板的基礎木材則是秋田的栗木。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/04/26-25268.webp"]'::jsonb, E'2017-09-29'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/3513', E'zh-Hant', 39, E'高知城', E'高知城（日語：高知城／こうちじょう，羅馬化：Kōchi-jō）是位於日本高知縣高知市（舊土佐國土佐郡高知）的一座城堡，別名「鷹城」。\n\n高知城在江戶時代是土佐藩的藩廳。高知城在江戶時代修築的天守及本丸御殿、追手門等建築仍有保存，是日本的史跡並被選入日本100名城。\n\n高知城位於高知平原中心處的大高坂山上，是梯郭式平山城。高知城利用大高坂山南側的鏡川和北側江之口川為天然護城河。在戰國時代之前，高知城名為大高坂山城。\n\n現在的高知城由江戶時代初期土佐藩初代藩主山內一豐興建，在第二代藩主山內忠義時期竣工。山內一豐時期，高知城名為河中山城，後改名為高智山城，再改為現名。高知城躲過了明治時期廢城令及太平洋戰爭的影響，是日本唯一本丸內建築得到完全保留的城郭。天守、御殿、追手門等15棟建築都得以現存，是日本的重要文化財。城郭全體現在是高知公園，免費對公眾開放，但天守及本丸御殿需付費參觀。高知城附近地區城聚集有高知市政府、高知縣政府、地方法院、地方檢察院等行政和司法機構，是高知縣的行政中心。城內有山內一豐及妻子千代（見性院）、板垣退助的銅像。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/03/17-21572.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/17-21561.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/13-101302.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/03-85127.webp"]'::jsonb, E'2016-10-27'::timestamptz, E'高知城', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E9%AB%98%E7%9F%A5%E5%9F%8E'),
(E'https://matcha-jp.com/tw/9946', E'zh-Hant', 39, E'自己烤的格外好吃！高知特色美食「稻草烤鰹魚」名店推薦', E'說到四國高知，很多人都會想到龍馬，但其實老饕們都知道高知也充滿美食！其中一項高知名產就是鰹魚，在日本多半用鰹魚來做高湯，但高知人除了用作高湯外，還直接炙燒食用。這次Matcha小編帶大家親手烤鰹魚，也為大家介紹一間位在弘人市場的知名稻草烤鰹魚餐廳。\n\n四國高知縣的其中一種名物就是鰹魚，一般在日本聽到鰹魚，多半是用鰹魚來做高湯，鰹魚高湯在日本料理中相當常見，所以一般在超市都可以輕易入手。但來到高知，鰹魚除了用作高湯外，還可以直接食用，這次Matcha小編帶大家親手烤鰹魚，也為大家介紹一間高知市內知名的稻草烤鰹魚餐廳。\n\n高知市內的弘人市場，有家餐廳每天都是人山人海，偶然還會看到熊熊火光，那就是市內的人氣稻草烤鰹魚店「明神丸」。稻草烤鰹魚即是日語的「鰹のたたき(Katsuo-no-tataki)」一般高知的稻草烤鰹魚，都是用稻草來燒鰹魚，把鰹魚的表面輕輕的烤熟，大概3分熟的時候便拿起，再切成片狀，吃的時候搭配蒜片、洋蔥和紫蘇，然後再沾上柚子柑橘醬或輕灑一點鹽巴來吃。\n\n他們還會在現場用稻草烤鰹魚，遠看店舖冒出熊熊烈火，馬上吸引許多上門觀賞、排隊購買的客人。炙燒過後的鰹魚片，逼出表面的魚油，帶點油香又不會太膩，而且還送來微微的草香氣，這種獨特的口味只有在高知才會吃到。', E'["https://resources.matcha-jp.com/resize/720x2000/2020/07/06-104704.webp","https://resources.matcha-jp.com/resize/720x2000/2020/07/06-104705.webp","https://resources.matcha-jp.com/resize/720x2000/2020/07/06-104706.webp","https://resources.matcha-jp.com/resize/720x2000/2020/07/06-104699.webp"]'::jsonb, E'2020-07-06'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/3648', E'zh-Hant', 39, E'來到四國高知就要這樣吃！高知著名必吃在地美食七選', E'位於四國的高知縣，氣候溫暖多雨，自然生態豐富，不只是金目鯛等魚類海鮮，各種高知縣道地的鄉土料理像是土佐和牛也非常有名，更多次在「擁有最多當地特色美食」的調查中位居第一，這次就一起來看看，來到物產豐富的高知縣，必吃哪七項特色在地美食吧！\n\n位於四國的高知縣，氣候溫暖多雨，自然生態豐富，不只是魚類海鮮，各種高知縣道地的鄉土料理也非常有名，更多次在「擁有最多當地特色美食」的調查中位居第一，這次就一起來看看，來到物產豐富的高知縣，必吃哪種特色到地美食吧！\n\n鰹魚是一種迴游性魚類，在五月時會迴游到日本沿海。在高知最知名的吃法，就是用成束的稻草生火來烤新鮮的鰹魚，烤出來的表面香氣四溢，內部多汁可口，再加上大量的蔥蒜，就是最道地的吃法了！在秋季時高知的鰹魚極為肥美，除了直接吃炙烤鰹魚，加工過後的酒盜（鹽漬鰹魚內臟）、角煮（切塊燉煮鰹魚）及柴魚片等，都是高知最經典的鰹魚伴手禮。\n\n位於高知縣東南方室戶，以海洋深層水而聞名，生長於此的金目鯛，身體為美麗的紅色，在冬天產季時最為肥美。金目鯛可說是高級魚的代表，不管是製成生魚片、丼飯，或是用煮的用烤的都相當美味。在高知品嚐金眼鯛，可以吃到當天捕獲金目鯛的生魚片，並品嘗金目鯛熬煮成的湯品，一魚兩吃是這裡的代表吃法之一。', E'["https://resources.matcha-jp.com/resize/720x2000/2016/12/14-11618.webp","https://resources.matcha-jp.com/resize/720x2000/2016/11/24-10185.webp","https://resources.matcha-jp.com/resize/720x2000/2016/12/14-11619.webp","https://resources.matcha-jp.com/resize/720x2000/2016/11/24-10203.webp"]'::jsonb, E'2016-12-14'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/1354', E'zh-Hant', 40, E'【2026】飽覽北九州之秋！福岡、大分、佐賀賞楓景點19選', E'福岡以優美自然、熱心腸的人們還有眾多美食而知名，吸引不少觀光客前來造訪。在秋天來訪福岡的話，請一定要去看楓葉，而且不只福岡，鄰近的佐賀和大分也有很多壯觀的楓葉美景。本篇介紹19處秋天來訪九州北部的熱門賞楓景點。\n\n位於九州地方北部的福岡，以優美自然、熱心腸的人們還有眾多美食而知名。若是秋天來訪福岡的話，請一定去觀賞紅葉。本篇除了福岡的紅葉景點外，也介紹鄰近的大分和佐賀的紅葉景點，方便大家一起規劃追紅葉！\n\n九州北部例年的紅葉觀賞時期為11月上旬〜11月下旬(有些地方為12月上旬)前後。請注意根據當年氣候和地區而定，紅葉觀賞時期略有不同。\n\n「舞鶴公園」是以福岡城遺跡為中心的公園。福岡城是建於江戶時代的城堡，現在仍殘留有石牆和箭樓(※1)，令人追憶往昔。作為公園開放以來，成為了市民的休息場所。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/07/13-58455.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/17-58553.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/13-58458.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/13-58457.webp"]'::jsonb, E'2018-11-14'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/1648', E'zh-Hant', 40, E'【2026最新】九州賞櫻景點10選！迷人的大自然和櫻花絕景', E'春天時來日本的話，不容錯過觀賞櫻花！本篇介紹在九州地方7縣可以觀賞的櫻花絕景景點10選。從人氣觀光地到面向行家的秘境景點。請過目九州獨有的各種豔麗櫻花。\n\n九州地方位於日本南西部。以氣候溫暖及自然富饒而為人熟知。在櫻花季節，根據地區而定，能夠觀賞到各種不同的景色。\n\n在關東地方見不到的櫻花絶景令人意想不到地為之著迷。本篇精選介紹10處九州地方的秘藏櫻花景色。\n\n預估九州開花時間會在 3 月 21 日至 26 日之間，滿開落在 3 月30 日至 4月4日之間。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/01/28-121781.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/28-121782.webp","https://resources.matcha-jp.com/resize/720x2000/2018/02/05-47341.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/28-121783.webp"]'::jsonb, E'2016-03-28'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/5705', E'zh-Hant', 40, E'【2026最新】福岡櫻花景點14選：在地人都在舞鶴公園、西公園、小倉城、淺井一本櫻等地賞櫻', E'九州的美食重鎮ー福岡，當季節的指針轉向了春天，福岡就自動披上一席稱為「櫻花」的粉嫩外衣，福岡市區的舞鶴公園、西公園，北九州的小倉城，筑後地區的淺井一本櫻等等美景都讓旅客流連忘返。\n\n九州的美食重鎮ー福岡。來到這個九州指標性交通城市，除了數不清的美食會讓旅客滿足之外，當季節的指針轉向了春天，福岡就會自動披上一席稱為「櫻花」的粉嫩外衣，如夢似幻的景色讓旅客流連忘返。\n\n※2026年福岡櫻花的開花日預估在3/21 ，滿開日則是落在3/30左右。（資訊來源：日本氣象廳）\n\n不知道也沒關係，本次就針對福岡縣的四大區域（福岡地區、筑後地區、筑豐地區、北九州地區），本次由福岡市中心向外延伸來分享13處福岡必去的賞櫻景點！', E'["https://resources.matcha-jp.com/resize/720x2000/2018/01/29-46849.webp","https://resources.matcha-jp.com/resize/720x2000/2018/01/29-46856.webp","https://resources.matcha-jp.com/resize/720x2000/2018/01/29-46857.webp","https://resources.matcha-jp.com/resize/720x2000/2018/01/29-46859.webp"]'::jsonb, E'2018-01-29'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/11344', E'zh-Hant', 41, E'【2026】西九州新幹線沿線攻略！景點介紹、轉乘方式、車輛介紹', E'日本新幹線路線「西九州新幹線」是從佐賀縣的武雄溫泉站連接至長崎縣的長崎站，全長共66公里。伴隨著這條路線開幕，福岡至長崎的移動時間也大幅縮短了30分鐘！現在就趕快跟小編好好認識這一條全新路線及沿線景點吧！\n\n西九州新幹線只有66公里，共五座車站，分別是武雄溫泉站、嬉野溫泉站、新大村站、諫早站、長崎站，每站都有不少觀光景點。\n\n藉由西九州新幹線的開業，從福岡至長崎的距離與時間縮短不少，長崎有許多歷史與人文相關的景點，相當值得走訪一趟。利用JR九州推出的鐵路周遊券就可以搭乘最新的西九州新幹線喔！ 小編推薦延伸閱讀 【最新】長崎縣觀光景點詳細指南！嚴選30處旅遊景點 長崎縣', E'["https://resources.matcha-jp.com/resize/720x2000/2022/09/13-129754.webp","https://resources.matcha-jp.com/resize/720x2000/2022/09/13-129755.webp","https://resources.matcha-jp.com/resize/720x2000/2022/09/13-129753.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/28-123335.webp"]'::jsonb, E'2022-09-13'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/10410', E'zh-Hant', 41, E'推薦給愛酒人士！透過「鹿島嬉野酒藏之旅」體驗九州自豪的日本酒文化', E'位於日本九州地方的佐賀縣鹿島市、嬉野市，有著饕客不可錯過的日本酒和飲食文化。本篇文章將介紹2天的酒藏之旅，發現許多美味日本酒與其文化。\n\n鹿島市內不少釀酒廠具有200年以上的歷史，其中還有幾間酒廠對外公開歡迎觀光客拜訪，正好是可以了解並享受味道纖細的日本酒的最佳場所。\n\n在這兩天的鹿島嬉野酒藏之旅中，漫步在江戶時代的街道上，品嚐著各式各樣的美酒和當地美食，還可以體驗釀酒過程呢！\n\n第一天，在日本三大拉麵之街—福岡縣的博多與導遊會合。想到接下來能體驗的美酒和美食，內心興奮不已，大夥兒一同搭上計程車，出發前往鹿島。', E'["https://resources.matcha-jp.com/resize/720x2000/2021/02/23-112555.webp","https://resources.matcha-jp.com/resize/720x2000/2021/02/24-112578.webp","https://resources.matcha-jp.com/resize/720x2000/2021/02/23-112537.webp","https://resources.matcha-jp.com/resize/720x2000/2021/02/23-112538.webp"]'::jsonb, E'2021-03-05'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/7306', E'zh-Hant', 41, E'【2026最新】玩九州「佐賀」看這一篇就OK！景點13選、美食、溫泉、交通、天氣', E'佐賀有什麼好玩的？佐賀景點有哪些？必吃佐賀美食是？關於九州佐賀的所有疑難雜症都在本篇一次解答，有在計劃到佐賀自由行的人，看這篇就對了！就算只要佐賀一日遊的人，也一定可以在這裡找到實用的資訊！\n\n五彩繽紛的熱氣球節、浮在水面上的紅色鳥居，壯美的梯田景色、鮮美多汁的佐賀牛等，只有來位於九州的佐賀來才能實現了。今天將會詳細介紹佐賀景點、佐賀美食等所有關於佐賀的吃喝玩樂，趕快來看一下吧！\n\n佐賀縣具體可以分為四大地區。分別是縣政府所在的「佐賀市」，沿海的「唐津地區」，因「有田燒」陶瓷器而聞名的「有田・武雄地區」和有 OUTLET 的「鳥栖地區」。\n\n佐賀縣內的交通主要是電車和巴士，不過班次都很少。而且有些景點距離車站都有些距離，所以預算充足的情況下，推薦租車自駕比較方便。從博多出發前往佐賀，搭乘電車、特急、高速巴士都可以抵達。', E'["https://resources.matcha-jp.com/resize/720x2000/2026/02/20-259445.webp","https://resources.matcha-jp.com/resize/720x2000/2026/02/20-259459.webp","https://resources.matcha-jp.com/resize/720x2000/2026/02/20-259451.webp","https://resources.matcha-jp.com/resize/720x2000/2026/02/20-259443.webp"]'::jsonb, E'2019-06-06'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/3913', E'zh-Hant', 42, E'【最新】長崎縣觀光景點詳細指南！嚴選30處旅遊景點', E'位於九州地區的長崎縣是日本人氣觀光地。長崎有歷史悠久的觀光景點，與日本三大中華街之一的長崎新地中華街等眾多觀光地。本篇文章將向大家介紹長崎縣的30個經典景點，完整解析長崎魅力。\n\n位於九州地方的長崎縣是東西文化交匯，富有異國風情的城市。同時，這裡也是第二次世界大戰原子彈的投擲點，因此這裡和廣島一樣, 在世界上也有一定的知名度。\n\n長崎的氣候適合全年旅遊，夏季短暫且濕熱，白天氣溫可達30°C左右，建議穿著輕便的短袖衣物並準備防曬用品。冬季則比較冷，氣溫大約在5°C到10°C之間，且常有寒冷的海風，此時必備防風厚外套和圍巾。春季和秋季氣候宜人，特別是9月中到10月下旬的秋季，天氣最為舒適，適合各種戶外活動。此外也是當地傳統活動的高峰期，除了享受美麗的自然景色，還能深入體驗長崎獨特的文化氛圍。\n\n如果是從東京、大阪到長崎的話可以直接搭乘飛機至長崎機場，再搭乘巴士到長崎市區或其他地區都很方便。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/11/09-208256.webp","https://resources.matcha-jp.com/resize/720x2000/2022/09/13-129752.webp","https://resources.matcha-jp.com/resize/720x2000/2023/10/06-147944.jpeg","https://resources.matcha-jp.com/resize/720x2000/2020/04/07-100975.webp"]'::jsonb, E'2018-04-12'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/10916', E'zh-Hant', 42, E'原來這些特色車站都在長崎！不是鐵道迷也會愛的私房景點5選', E'許多旅人都喜歡到日本進行「鐵道旅行」，而鐵道旅之中也有不同的方式。這次Matcha小編帶大家去到九州「長崎」，來趟輕鬆慢活的鐵道旅行，造訪擁有絕景的無人車站、日本最西端車站，再帶回到市內搭乘可愛的尾曲貓路面電車。\n\n到訪同時，別忘了到車站內的扭蛋機取得「幸福的黃色手帕」寫下心願繫在月台的欄杆上。\n\n鐵道站旅行可說是個不錯的旅行方式，不過如果不開車的話，要抓住班次也不容易，特別是途經無人站的班次不多，出發前一定要多作準備。換個角度看，這種旅行方式反而讓人步調跟著放慢，未嘗不是一個讓放鬆心情的好方法。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/02/04-122255.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/04-122256.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/04-122257.webp","https://resources.matcha-jp.com/resize/720x2000/2022/02/04-122258.webp"]'::jsonb, E'2021-10-29'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/9813', E'zh-Hant', 42, E'【長崎景點】搭上路面電車，來趟轉動歷史之輪的深度長崎之旅', E'長崎市不只有百萬夜景，長崎市內的建築、飲食文化都有著東西文化融合的痕跡，整個長崎市就像是本立體的歷史教科書，今天MATCHA小編就要帶大家來一趟長崎市區的歷史文化之旅。\n\n長崎市區地形高低起伏大，市區中擁有許多坡道，所以在日本之中是腳踏車普及率數一數二低的城市。加上路面狹窄，單行道多且複雜，路邊停車不方便，若想在市區遊玩，自駕、騎腳踏車恐怕都不是好選項。但別擔心，搭乘長崎路面電車，就夠我們悠遊市區景點啦！\n\n長崎路面電車搭乘一趟是130日圓，行程上若單日搭超過3趟，就不妨購買600日圓的一日券，不只經濟實惠，還可省下轉車時需要告知司機領取換乘券的手續。\n\n不過切記車上不會販賣一日券，請至官網確認各車站附近的販售地點與時間，識別度最高的販售點就是JR長崎站的綠色窗口 (みどりの窓口)。一日券是自行刮開使用日期，因此當天一早購買或事前購買都可。（一日券繁體中文簡介、實體一日券販售地點）', E'["https://resources.matcha-jp.com/resize/720x2000/2020/05/21-103123.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/07-100978.webp","https://resources.matcha-jp.com/resize/720x2000/2020/05/21-103124.webp","https://resources.matcha-jp.com/resize/720x2000/2020/05/21-103125.webp"]'::jsonb, E'2020-05-21'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/21040', E'zh-Hant', 43, E'【最新】熊本必買伴手禮10選：居民也愛的「這味」在熊本車站一次買齊', E'熊本市區有許多專門販售伴手禮的地方，但是說到能買到具有熊本特色，品項又非常齊全的，非常推薦來到JR熊本車站！ 小編住在熊本每次需要買伴手禮送人的時候，首選都會去JR熊本車站。因為種類豐富，有符合各種年齡層的伴手禮，甚至有些只有在這裡才可以買到的限定品。本篇會介紹10個熊本必買伴手禮給各位參考！\n\nJR熊本車站是目前熊本市區內匯集最多伴手禮的地方，本篇介紹的10個熊本伴手禮是小編自己很愛吃，或者熊本當地人推薦的，歡迎大家參考。\n\n費南雪使用熊本縣產的阿蘇澤西牛乳和米製粉烤成，一打開就有濃濃的奶油香氣，是不論大人小孩都會喜歡的伴手禮。\n\n一直都是熊本人氣伴手禮之一的「天草奶油餅乾」，於2023年底推出新產品「天草奶油夾心餅乾」！原本就已經很美味的奶油餅乾夾上滿滿的奶油霜，美味更升級，是小編最近最愛的零食之一。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/08/14-192444.webp","https://resources.matcha-jp.com/resize/720x2000/2024/08/14-192448.webp","https://resources.matcha-jp.com/resize/720x2000/2024/08/14-192449.webp","https://resources.matcha-jp.com/resize/720x2000/2024/08/15-192450.webp"]'::jsonb, E'2024-08-14'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/3153', E'zh-Hant', 43, E'【2026最新】超完整「熊本」自由行攻略！景點17選、熊本美食、路面電車搭法', E'熊本不僅有熊本城、阿蘇火山、熊本熊廣場等人氣景點，還有熊本美食像是熊本拉麵、生馬肉等。最近又因為台積電熊本廠造成許多話題！本文將介紹熊本景點、熊本溫泉、熊本住宿等實用熊本旅遊資訊，讓你的熊本自由行可以順順利利！\n\n熊本有「日本最大」的破火山口「阿蘇山」和阿蘇周邊有名的溫泉鄉。而大文豪「夏目漱石」筆下的《森林之都》，到熱血動漫《航海王》作者「尾田榮一郎」老師的出身地也都和熊本密切相關，加上豐富的自然資旋如番茄、草莓等農產品，讓熊本成為日本知名的觀光景點。\n\n這篇文章要來介紹熊本景點、熊本美食、熊本住宿等超實用熊本旅遊資訊，甚至會手把手帶大家看怎麼搭乘熊本路面電車喔！\n\n熊本春天（3月～5月）：氣溫逐漸變暖，白天約在 15 ～ 25 度之間。櫻花盛開，是欣賞熊本櫻花的最佳季節！建議穿著輕便外套和薄長袖，選擇方便活動和野餐的服裝。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/12/17-215640.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/11-196717.webp","https://resources.matcha-jp.com/resize/720x2000/2017/07/30-32461.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/16-215525.webp"]'::jsonb, E'2017-01-11'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/22574', E'zh-Hant', 43, E'熊本購物就去這些地方！在地商店街、百貨公司、購物商場14選', E'近期熊本因為直飛航班的開設和台灣半導體廠商的進駐，讓熊本成為來日旅遊和移居的熱門縣市，本記事將由住在熊本多年的小編向大家介紹熊本購物的好去處！包含在地人觀光客都愛去的商店街、百貨公司和大型購物商場等資訊，熊本的商店街和百貨公司各有不同的風格和客群，大家可以依照自己喜歡的類型來安排購物行程。\n\n下通商店街是熊本市內最大的商店街，全長約511公尺，不只有星野集團飯店OMO5、百貨公司、各式各樣的個性小店、居酒屋、咖啡廳、夾娃娃機店、24小時連鎖餐廳、唐吉訶德、藥妝店、熊本必吃拉麵「黑亭」和太平燕名店「紅蘭亭」等都聚集在下通商店街，這邊也常常會有各種街頭表演和展示活動，是觀光客和當地居民常常購物的地方。\n\n下通商店街尾端右轉往櫻町交通中心的一小段路，當地人稱這條路為「新市街」，除了有多家飯店例如CANDEO HOTELS、Richmond之外，還有來熊本必吃的「勝烈亭豬排本店」、小編很喜歡吃的「魚介沾麵ONNNOJI」。\n\n如果想了解新市街的店家資訊，小編發現商店街抬頭有QR CODE碼可以掃，也有繁體中文頁面，歡迎大家利用。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/11/11-208334.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/11-208335.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/11-208338.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/11-208341.webp"]'::jsonb, E'2024-11-09'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/7395', E'zh-Hant', 44, E'【2026】大分景點18選！除了別府由布院，這些「神級美景」你去過了嗎？', E'大分不只有別府與由布院，本篇精選18個大分景點和大分美食。從知名大分溫泉、絕景自然到古寺神社，幫你規劃日本大分深度行程。無論想泡湯放鬆、賞景攝影或品嚐當地風味，這份大分自由行攻略都能帶你發掘大分最具魅力的旅遊體驗！\n\n看完這篇後，一起來大分泡湯、享用美食、欣賞山海、走訪寺院，徹底感受大分的魅力吧！\n\n※1：由布院(ゆふいん)……由布院有兩種稱法，分別為「由布院」及「湯布院」，車站等會是標示成「由布院」。\n\n大分縣位於九州地方東部的縣市，與福岡縣、熊本縣、宮崎縣相鄰。大分縣有大分機場，可以從台灣直飛！', E'["https://resources.matcha-jp.com/resize/720x2000/2026/04/14-262724.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/23-75877.webp","https://resources.matcha-jp.com/resize/720x2000/2023/06/20-139692.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/13-76699.webp"]'::jsonb, E'2019-06-19'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/7502', E'zh-Hant', 44, E'宇佐神宮', E'宇佐神宮（うさじんぐう）是位於日本大分縣宇佐市的神社。為式內社（名神大社）、豐前國一宮、舊社格為官幣大社（現神社本廳的別表神社）。\n\n日本全國4萬4千座八幡宮之總本宮、也通稱宇佐八幡或宇佐八幡宮。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/06/01-78471.webp","https://resources.matcha-jp.com/resize/720x2000/2019/06/01-78476.webp","https://resources.matcha-jp.com/resize/720x2000/2019/06/01-78475.webp","https://resources.matcha-jp.com/resize/720x2000/2019/06/01-78472.webp"]'::jsonb, E'2019-06-01'::timestamptz, E'宇佐神宮', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E5%AE%87%E4%BD%90%E7%A5%9E%E5%AE%AE'),
(E'https://matcha-jp.com/tw/19455', E'zh-Hant', 44, E'【2026】九州觀光列車「由布院之森」完整攻略：購票與預約劃位技巧、時刻表、停靠站資訊', E'想搭乘九州超人氣觀光列車「由布院之森」？本篇彙整了2026 年時刻表、路線與停靠站，詳細教你預約、劃位與購票步驟，並公開提高訂票成功率的實用密技與注意事項，適合從博多出發規劃由布院或別府行程的旅客，一次掌握所有重點，讓列車之旅更順暢。\n\n目次 觀光列車「由布院之森」簡介 「由布院之森」跟特急「由布」差在哪？ 由布院之森行駛路線和停靠車站 由布院之森時刻表(2026年最新版) 由布院之森車內特色 如何預約由布院之森 如何以較高機率預約到「由布院之森」列車呢？ 觀光列車「由布院之森」簡介 由布院之森外觀 Photo by Pixta 湯布院溫泉一直是九州相當出名的溫泉地，也是著名的度假村，充滿了自然風光也有許多和風建物和庭園，每年都有許多觀光客造訪，近年更是在海外觀光客之中有超高人氣，前往湯布院溫泉很多人會選擇搭乘觀光特急由布院之森。它的設計師是著名的水戶岡鋭治，這台列車是他的代表作之一，其翠綠色外觀和內裝都相當有特色，是九州最具代表性的觀光列車之一。也因為在外國旅客中擁有超高人氣，全車為指定座位，所以預約難度大幅提升。\n\n在沒有任何JR PASS的情況下，車錢加上特急指定席費用如下： 博多站至由布院站：5,690日圓\n\n特急由布 Photo by Pixta 特急由布基本上和由布院之森行走路線是完全一樣的，但終點站設定在別府或大分，停車站也較多。但例外的是由布院之森沒行駛的時候，該時刻表就會是由特急「由布」車型代替行走，且停車站也一樣。一般來說博多站每天會有2班來回於別府之間，來回於大分之間有一班。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/04/19-177532.webp","https://resources.matcha-jp.com/resize/720x2000/2024/04/19-177533.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/15-233457.webp","https://resources.matcha-jp.com/resize/720x2000/2024/04/19-177542.webp"]'::jsonb, E'2024-04-19'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/7488', E'zh-Hant', 45, E'【宮崎】「高千穗がまだせ市場」幫你搞定人氣伴手禮7選！', E'以充滿仙氣的「峽谷」景觀而聞名世界的高千穗，除了是個自然景觀豐富的觀光寶庫之外，海拔300多公尺高的地形間接孕育出了不同於平地的食材。若不想東奔西跑來買齊高千穗伴手禮的話，就得來一趟在地人也每天逛的蔬果土產商店「高千穂がまだせ市場」。\n\n位於九州宮崎縣北方的高千穗是日本國民公認的絕景聖地，來到了高千穗除了可以租借小船來暢遊涼爽的高千穗峽谷，也可以漫步於充滿古代氣息的天岩戸神社、天安河原等能量景點，抑或是預約一間可以泡湯的日式旅館來徹底放空。\n\n「高千穗がまだせ市場」為一棟複合式的商業觀光設施，裡頭包含了可以購賣地產蔬果、各式加工土產的「鬼八之藏（鬼八の蔵）」、可享用高千穗牛料理的「餐廳和（レストラン和）」，以及可以直接購買高千穗牛肉的「JA高千穗地區肉品中心（JA高千穂地区ミートセンター）」。\n\n而作為設施名稱的「がまだせ」則為當地的方言，含有「提起精神！加油！」的意思，也同時意味著高千穗地區想要「使用當地特產來振地觀光」的抱負與期盼。本篇的重點將放在可以購買當地各種特產品的「鬼八之藏」，以下將進行詳細的商店介紹。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/05/23-77552.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/30-78205.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/30-78207.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/30-78208.webp"]'::jsonb, E'2019-05-29'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/26417', E'zh-Hant', 45, E'【宮崎美食攻略】不只有宮崎牛！南蠻雞始祖、炭火地雞與芒果甜點，跟著在地人推薦一起吃', E'宮崎被譽為「日本肉食倉庫」，從連續四屆奪冠的宮崎牛、南蠻雞發源地到炭火地雞，這裡絕對是肉食者的天堂！本文整理宮崎必吃美食清單，包含預約困難的鐵板燒名店、在地人收尾的釜揚烏龍麵以及夢幻芒果甜點。\n\n推薦名店「一ッ葉ミヤチク」，這間在地老字號的宮崎牛専門店，以鐵板燒和壽喜燒料理宮崎牛聞名，常常被選入百名店名單。主廚現場以高溫鐵板逼出牛肉油花香氣，外層微焦、內裡粉嫩，是體驗宮崎牛最佳方式之一。當地人與旅客常於晚餐時段預約造訪，搭配當地酒品更是美味。\n\n宮崎車站附近的洋食屋「味のおぐら 本店」，位於宮崎市區的小巷內，外觀充滿昭和時代的復古風情。他們的南蠻雞份量驚人，濃郁的塔塔醬是自家秘製，數十年來口味未變，用餐時間總是排著長長的人龍。\n\n宮崎地區知名的連鎖店「辛麵屋 桝元」，市區的本店開放式座位適合旅人短暂停留，也能自由選擇從微辣到超級辣的各種辣度，是嚐試宮崎辛麵的絕佳第一站。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/12/14-252836.webp","https://resources.matcha-jp.com/resize/720x2000/2025/12/14-252837.webp","https://resources.matcha-jp.com/resize/720x2000/2025/12/14-252838.webp","https://resources.matcha-jp.com/resize/720x2000/2025/12/14-252839.webp"]'::jsonb, E'2025-12-12'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/9715', E'zh-Hant', 45, E'【宮崎景點】到小鎮走訪戰國足跡！古色古香的「綾城」', E'不知道大家對宮崎有什麼印象呢？在2020年初，一群來自香港的學生到宮崎做交流活動。他們去了宮崎縣綾町的綾城，讓我們跟著他們的腳步認識這古色古香且名字優美的綾城吧！\n\n這些香港的同學們第一站就去了位在宮崎市區西側的綾町，綾町距離宮崎機場大約一小時車程，位於宮崎縣西部內陸地區，人口未滿7000的小鎮。從宮崎市區出發後，沿途建築物慢慢消失，風景慢慢轉為綠油油的田園風光，是自駕遊的好去處。\n\n綾城建於日本鎌倉時代末期的南北朝之時，公元1331至1334年，由足利尊氏的家臣細川小四郎義門築城。後來細川小四郎義門的兒子——細川義遠在綾的山上興建了要塞城堡，從此自稱為綾氏，所以這個城堡就命名為綾城。綾城也就是同學們在綾町最主要的參觀行程。\n\n同學們玩得非常開心。 進入戰國時期，綾氏投入日向（現：宮崎）豪族的伊東氏麾下，綾城也一直是抵禦薩摩（現：鹿兒島）島津氏進攻的最前線，伴隨著伊東氏勢力沒落，綾城被攻下後也成為島津氏的支城之一。進入江戶時代後，幕府於1615年下令實施一國一城令，綾城被廢城。根據綾城門口石碑紀錄，現在城內的天守閣是在1985年所重建的。園區內還有一塊明仁天皇（現上皇）在光臨綾城時所立的紀念石碑。', E'["https://resources.matcha-jp.com/resize/720x2000/2020/04/22-101944.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/22-101947.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/22-101948.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/22-101951.webp"]'::jsonb, E'2020-04-22'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/24866', E'zh-Hant', 46, E'【2026】鹿兒島購物逛街要去哪？精選8個市區百貨、商店街、購物中心', E'不要以為鹿兒島市區沒地方逛街，其實可以購物買伴手禮、藥妝的設施非常多！不管是鹿兒島中央車站附近，還是天文館商店街，唐吉訶德，甚至是郊區的大型購物中心，來到鹿兒島一定也可以滿足旅客的購物慾望。\n\n目次 1.鹿兒島中央站 AMU PLAZA鹿兒島 2.天文館商店街 3.山形屋 4.Maruya Gardens 5.Frespo Jungle Park 6.唐吉訶德天文館店 7.唐吉訶德鹿兒島中央一番店 8.AEON MALL鹿兒島 1.鹿兒島中央站 AMU PLAZA鹿兒島 JR鹿兒島中央車站共構的「AMU PLAZA鹿兒島」是九州南部最具代表性的大型商業設施之一，不僅交通便利，更是集結購物、美食與娛樂於一棟的指標性景點，其外觀的摩天輪也是鹿兒島市區的地標。本館與Premium館內擁有超過200間店鋪，涵蓋國內外流行服飾、生活雜貨、化妝品、書籍以及鹿兒島限定的特產與伴手禮等，商品種類繁多，能滿足各年齡層的購物需求。 JR鹿兒島中央站\n\n鹿兒島市中心最繁華的「天文館商店街」是南九州最具代表性的商店街。其名稱源於江戶時代薩摩藩主島津重豪為觀測天文、製作曆書而設立的「明時館」所在地。有屋頂的街道縱橫交錯，匯集了眾多商店，從老字號百貨、鄉土料理餐廳、鹿兒島特產店、流行服飾店到藥妝店、咖啡廳等應有盡有。\n\n知名的「白熊」刨冰發源店「無邪氣」也在商店街內，也能品嚐到黑豬肉料理、薩摩炸魚板等豐富的在地美食，是觀光客與當地居民享受購物、美食和感受鹿兒島日常氛圍的最佳去處。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/05/30-234936.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/30-234941.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/30-234940.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/30-234937.webp"]'::jsonb, E'2025-05-07'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/24865', E'zh-Hant', 46, E'享受鹿兒島縣的在地魅力！深受當地人喜愛的6個觀光及購物景點推薦', E'鹿兒島有很多必去景點，但這次要告訴鹿兒島當地人也愛去的地方，像是當地人也會去的溫泉鄉、商店街、運動用品店、高爾夫球場等等，讓來造訪鹿兒島的訪日旅客可以體驗「最親近當地，最有生活感」的新型態旅行模式。\n\n鹿兒島地標 櫻島火山 Photo by PIXTA 說到九州的鹿兒島，大家可能會先想到雄偉的櫻島火山，但其實鹿兒島的魅力遠不止於此！鹿兒島擁有豐富的自然景觀、獨特的歷史文化，以及各式各樣的美食，因此吸引了許多國內外的遊客。無論你是喜歡泡溫泉、逛街購物，還是熱愛戶外活動，鹿兒島都能滿足你的需求。小編這次要介紹特別受到鹿兒島當地人喜愛的景點，保證讓你的鹿兒島之旅充滿驚喜與回憶。\n\n霧島溫泉 丸尾瀑布 Photo by PIXTA 如果是一位溫泉愛好者，那麼來到鹿兒島就不能錯過「霧島溫泉鄉」！這裡不僅擁有豐富的自然景觀，更以其多樣的泉質而聞名。\n\n從硫磺泉、明礬泉到鐵泉，每一種泉水都有其獨特的功效和特色，可以讓你在泡湯的同時，也達到療癒身心的效果。許多鹿兒島縣民在工作之餘，也喜歡來到霧島溫泉鄉，享受片刻的寧靜與放鬆。 霧島溫泉鄉', E'["https://resources.matcha-jp.com/resize/720x2000/2025/05/08-232922.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/08-232888.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/15-233503.webp","https://resources.matcha-jp.com/resize/720x2000/2025/05/15-233504.webp"]'::jsonb, E'2025-05-08'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/18238', E'zh-Hant', 46, E'【最新】鹿兒島縣10大推薦餐廳・土產・觀光景點', E'在受惠於大自然的鹿兒島，不只是有許多觀光景點，還有著連美食達人也會嘖嘖稱奇的珍味。本記事將以能品嚐到鹿兒島和牛及黑豬等在地美食的店家為中心，共介紹10間人氣名產店及觀光勝地。看完文章就趕快出發去鹿兒島旅遊吧 !\n\n鹿兒島縣位於日本本島的最南端。以日本首座被登錄為世界遺產的屋久島為首，奄美大島、徳之島等3個世界遺產都聚集在鹿兒島縣之中。\n\n受惠於大自然與氣候，鹿兒島和牛及黑豬、番薯與蠶豆等農產品的出產量是日本全國數一數二。有許多只有鹿兒島縣才有的珍味及特產，越是深入其中越會被鹿兒島縣的魅力所吸引。\n\n在本記事當中會介紹10間人氣名產店、觀光勝地、及可以品嚐到鹿兒島在地美食的餐廳。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/02/03-165214.webp","https://resources.matcha-jp.com/resize/720x2000/2024/02/03-165213.webp","https://resources.matcha-jp.com/resize/720x2000/2024/02/03-165215.webp","https://resources.matcha-jp.com/resize/720x2000/2024/02/03-165198.webp"]'::jsonb, E'2024-03-03'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/6875', E'zh-Hant', 47, E'【2026最新】日本最早櫻花搶先看！「沖繩」櫻花祭5選', E'沖繩的觀光魅力可不是只有絕美的海灘！沖繩其實是日本櫻花花季最早的地區，沖繩櫻花從1月中旬就會開始綻放至1月下旬。如果想欣賞沖繩櫻花的人，不要錯過本篇介紹的五個沖繩櫻花祭典！\n\n沖繩縣位於九州西南側的島，全年氣候溫暖，有很多漂亮的海灘，海上活動非常盛行有名。不僅日本人，就連海外的旅客都愛這個美麗的觀光勝地。\n\n首先，沖繩的櫻花花期是全日本最早的！ 由於沖繩氣候溫暖，櫻花大約會在1月中旬就開始綻放，可以說是日本最早開花的地區。\n\n第二個特色是沖繩的櫻花和本州的品種不同。本州常見的櫻花為「染井吉野櫻」，則沖繩較常看到的是「寒緋櫻」。寒緋櫻比染井吉野櫻顏色更濃更粉，花是向下開的。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/12/14-68105.webp","https://resources.matcha-jp.com/resize/720x2000/2018/12/14-68107.webp","https://resources.matcha-jp.com/resize/720x2000/2018/12/07-67657.webp","https://resources.matcha-jp.com/resize/720x2000/2018/12/07-67658.webp"]'::jsonb, E'2018-12-27'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/11504', E'zh-Hant', 47, E'【2026】 前沖繩縣民推薦的沖繩景點、美食、伴手禮、好逛超市總整理', E'沖繩第一次去該怎麼玩？有哪些沖繩美食必吃？本篇文章集結小編珍貴的在地生活經驗，嚴選出沖繩本島景點、推薦餐廳、內行人才會買的伴手禮、在地人逛的超市等。一起解鎖最深度的沖繩攻略！\n\n小編是前沖繩縣民，以前曾經有一段時間住在沖繩，所以對沖繩算了解。以下這篇文章以個人經驗為基礎，主要會介紹沖繩本島景點、美食（會放上推薦餐廳）、好逛的購物設施和自己也會想吃的伴手禮。\n\n除了最主要的本島之外，其實沖繩縣整體由 160 個島嶼所組成。是不是比想像中多呢？而大家熟悉的「那霸機場」和「那霸市」位於面積最大的沖繩本島。\n\n因為沖繩受到歷史上的琉球王國時代與美軍佔領時代影響，兩者文化深深滲透於沖繩，是有點像日本又有點不像日本的地方。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/06/05-55738.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/30-206659.webp","https://resources.matcha-jp.com/resize/720x2000/2018/06/07-55846.webp","https://resources.matcha-jp.com/resize/720x2000/2022/12/09-132781.webp"]'::jsonb, E'2022-12-07'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/6333', E'zh-Hant', 47, E'石垣島天文台', E'石垣島天文台（日語：石垣島天文台／いしがきじまてんもんだい）是位於日本沖繩縣石垣市的天文台，由自然科學研究機構國立天文台、石垣市、石垣市教育委員會、特定非營利活動法人八重山星之會、沖繩縣立石垣青少年之家、琉球大學共6間機構組成的協議會運營。\n\n天文台旨在藉由聯合運營這一新的形態，結合終身教育、學校教育，以及與業餘觀測家合作，推進各種活動。天文台白天自由參觀，夜間舉行天體觀望會（見#公開種類）。\n\n由於此地緯度低、黃道高，除提供公眾觀星服務外，亦主要圍繞行星科學及太陽系天體進行觀測。在所有設有大型光學紅外線反射望遠鏡的觀測研究設施中，此設施是日本最西及最南，望遠鏡口徑（105cm）亦為九州、沖繩地方中光學望遠鏡最大。\n\n除天文台外，石垣島亦在名藏地區設有VERA石垣島局，為國立天文台水澤VLBI觀測所的觀測點之一，使用相對特長基線干涉測量法（VLBI）觀測。該局主要進行繪製銀河系精密星圖方面的觀測，此外亦進行其他觀測活動，如透過精確測定地殼變動，觀測日本全體的地球板塊運動等。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/06/25-80276.webp","https://resources.matcha-jp.com/resize/720x2000/2018/07/18-58644.webp","https://resources.matcha-jp.com/resize/720x2000/2026/05/13-263990.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/29-221456.webp"]'::jsonb, E'2019-01-04'::timestamptz, E'石垣島天文台', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E7%9F%B3%E5%9E%A3%E5%B3%B6%E5%A4%A9%E6%96%87%E5%8F%B0')
